import React from 'react';

const Start = ({onStart, onPause, onReset}) => {
  return (
    <div className="grid grid-cols-3 gap-10 place-items-center width-80">
      <button
        id="start"
        className="w-full sm:w-24 md:w-32 lg:w-40 whitespace-nowrap p-3 sm:p-2 text-white shadow-sm text-lg sm:text-base md:text-base bg-white bg-opacity-20 rounded-lg hover:bg-opacity-5 hover:scale-105 transition duration-100 ease-in-out cursor-pointer"
        onClick={onStart}
      >
        start
      </button>
      <button
        id="pause"
        className="w-full sm:w-24 md:w-32 lg:w-40 whitespace-nowrap p-3 sm:p-2 text-white shadow-sm text-lg sm:text-base md:text-xl bg-white bg-opacity-20 rounded-lg hover:bg-opacity-5 hover:scale-105 transition duration-100 ease-in-out cursor-pointer"
        onClick={onPause}
      >
        pause
      </button>
      <button
        id="reset"
          className="w-full sm:w-24 md:w-32 lg:w-40 whitespace-nowrap p-3 sm:p-2 text-white shadow-sm text-lg sm:text-base md:text-xl bg-white bg-opacity-20 rounded-lg hover:bg-opacity-5 hover:scale-105 transition duration-100 ease-in-out cursor-pointer"
        onClick={onReset}
      >
        reset
      </button>
    </div>
  );
};

export default Start;
